mapper.select:
SELECT t.id, t.task_no, t.status, t.initiator_id
FROM inventory_task t

    JOIN inventory_item i ON i.task_id = t.id

WHERE t.id = #{id}

    AND 1 = 1
    AND i.department_id = #{departmentId}
    AND i.employee_id = #{employeeId}
    AND 1 = 0

LIMIT 1

SELECT i.id, i.task_id, i.archive_version_id AS expected_version_id, av.version_no AS expected_version_no, i.actual_version_id, i.employee_id, i.department_id, i.actual_status, i.difference_type, i.difference_description, i.checked_by, i.resolution_status, e.resolution, emp.employee_no AS employee_no, emp.name AS employee_name, d.title AS document_title FROM inventory_item i JOIN archive_version av ON av.id = i.archive_version_id JOIN archive_document d ON d.id = av.document_id JOIN employee emp ON emp.id = i.employee_id LEFT JOIN exception_record e ON e.id = ( SELECT MAX(e2.id) FROM exception_record e2 WHERE e2.inventory_item_id = i.id ) WHERE i.task_id = #{taskId} AND i.id = #{itemId}
AND 1 = 1 AND i.department_id = #{departmentId} AND i.employee_id = #{employeeId} AND 1 = 0
LIMIT 1

SELECT i.id, i.task_id, i.archive_version_id AS expected_version_id, av.version_no AS expected_version_no, i.actual_version_id, i.employee_id, i.department_id, i.actual_status, i.difference_type, i.difference_description, i.checked_by, i.resolution_status, e.resolution, emp.employee_no AS employee_no, emp.name AS employee_name, d.title AS document_title FROM inventory_item i JOIN archive_version av ON av.id = i.archive_version_id JOIN archive_document d ON d.id = av.document_id JOIN employee emp ON emp.id = i.employee_id LEFT JOIN exception_record e ON e.id = ( SELECT MAX(e2.id) FROM exception_record e2 WHERE e2.inventory_item_id = i.id ) WHERE i.task_id = #{taskId}
AND 1 = 1 AND i.department_id = #{departmentId} AND i.employee_id = #{employeeId} AND 1 = 0
ORDER BY i.id

mapper.update:
UPDATE exception_record SET status = 'RESOLVED', resolved_by = #{operatorId},
    resolved_at = CURRENT_TIMESTAMP, resolution = #{resolution}
WHERE inventory_item_id = #{inventoryItemId} AND status = 'OPEN'

UPDATE inventory_task SET status = #{toStatus},
    completed_at = CASE WHEN #{toStatus} = 'COMPLETED' THEN CURRENT_TIMESTAMP ELSE completed_at END
WHERE id = #{id} AND status = #{fromStatus}
